import json
import sys
profileType = sys.argv[1]
requestedTargetMoid = sys.argv[7]
requestedTargetObjectType = sys.argv[8]
profileMoid = sys.argv[9]
assignmentState = 'invalid'
stateMessage = ''
stateResult = '{}'
patchBody = ''
expectedRelationshipField = ''

def relationship(item, field, allowedTypes):
    value = item.get(field)
    if value is None or value == {}:
        return None
    if not isinstance(value, dict):
        raise ValueError(field + ' is not a relationship object.')
    moid = str(value.get('Moid', '')).strip()
    objectType = str(value.get('ObjectType', '')).strip()
    if not moid:
        raise ValueError(field + ' is a non-empty relationship object without a usable Moid.')
    if objectType not in allowedTypes:
        raise ValueError(field + ' contains an unexpected ObjectType.')
    return (moid, objectType)
try:
    target = json.loads(sys.argv[5])
    profileEnvelope = json.loads(sys.argv[6])
    results = profileEnvelope.get('Results')
    if not isinstance(results, list) or len(results) != 1 or (not isinstance(results[0], dict)):
        raise ValueError('The validated profile response no longer contains exactly one object.')
    profile = results[0]
    if str(profile.get('Moid', '')).strip() != profileMoid:
        raise ValueError('The profile Moid changed between validation and assignment.')
    targetMoid = str(target.get('Moid', '')).strip()
    targetObjectType = str(target.get('ObjectType', '')).strip()
    expectedTargetType = requestedTargetObjectType if profileType == 'Server' else 'equipment.Chassis'
    if targetMoid != requestedTargetMoid:
        raise ValueError('The target response Moid does not match the requested target.')
    if targetObjectType != expectedTargetType:
        raise ValueError('The target response ObjectType does not match the selected target type.')
    if profileType == 'Unified Edge' and (not str(target.get('Model', '')).strip().startswith('UCSXE-')):
        raise ValueError('The selected chassis is not a Unified Edge chassis (expected a UCSXE- model).')
    if profileType == 'Chassis' and str(target.get('Model', '')).strip().startswith('UCSXE-'):
        raise ValueError('A Unified Edge chassis must be assigned with Profile Type Unified Edge.')
    if profileType == 'Server':
        expectedRelationshipField = 'AssignedServer'
        relations = [relationship(profile, 'AssignedServer', {'compute.Blade', 'compute.RackUnit'}), relationship(profile, 'AssociatedServer', {'compute.Blade', 'compute.RackUnit'})]
        mode = str(profile.get('ServerAssignmentMode', 'None')).strip() or 'None'
        if mode not in {'None', 'Static', 'Pool'}:
            raise ValueError('ServerAssignmentMode contains an unsupported value.')
        if mode == 'Pool':
            assignmentState = 'conflict'
            stateMessage = 'The server profile is assigned through a resource pool and cannot be statically reassigned.'
        elif mode == 'Static' and (not any(relations)):
            raise ValueError('ServerAssignmentMode is Static but no assigned or associated server relationship is present.')
        elif mode == 'None' and any(relations):
            raise ValueError('ServerAssignmentMode is None but an assigned or associated server relationship is present.')
        else:
            existing = [r for r in relations if r]
            if any((moid != requestedTargetMoid or objectType != expectedTargetType for moid, objectType in existing)):
                assignmentState = 'conflict'
                stateMessage = 'The server profile is already assigned or associated with a different server.'
            elif existing:
                assignmentState = 'already'
                stateMessage = 'The server profile is already assigned to the requested server.'
            else:
                assignmentState = 'assign'
                stateMessage = 'The server profile is unassigned and ready for static assignment.'
                patchBody = json.dumps({'AssignedServer': {'ClassId': 'mo.MoRef', 'ObjectType': expectedTargetType, 'Moid': requestedTargetMoid}, 'ServerAssignmentMode': 'Static'}, separators=(',', ':'))
    elif profileType == 'Chassis':
        expectedRelationshipField = 'AssignedChassis'
        relations = [relationship(profile, 'AssignedChassis', {'equipment.Chassis'}), relationship(profile, 'AssociatedChassis', {'equipment.Chassis'})]
        existing = [r for r in relations if r]
        mode = profile.get('ChassisAssignmentMode')
        if mode not in ('None', 'Static'):
            raise ValueError('ChassisAssignmentMode is missing or unsupported.')
        if (mode == 'Static') != bool(existing):
            raise ValueError('ChassisAssignmentMode conflicts with assignment relationships.')
        if any((moid != requestedTargetMoid for moid, _ in existing)):
            assignmentState = 'conflict'
            stateMessage = 'The chassis profile is already assigned or associated with a different chassis.'
        elif existing:
            assignmentState = 'already'
            stateMessage = 'The chassis profile is already assigned to the requested chassis.'
        else:
            assignmentState = 'assign'
            stateMessage = 'The chassis profile is unassigned and ready for assignment.'
            patchBody = json.dumps({'AssignedChassis': {'ClassId': 'mo.MoRef', 'ObjectType': 'equipment.Chassis', 'Moid': requestedTargetMoid}, 'ChassisAssignmentMode': 'Static'}, separators=(',', ':'))
    elif profileType == 'Unified Edge':
        expectedRelationshipField = 'AssignedEntity'
        existing = relationship(profile, 'AssignedEntity', {'equipment.Chassis'})
        mode = profile.get('ChassisAssignmentMode')
        if mode not in ('None', 'Static'):
            raise ValueError('ChassisAssignmentMode is missing or unsupported.')
        if (mode == 'Static') != bool(existing):
            raise ValueError('ChassisAssignmentMode conflicts with AssignedEntity.')
        if existing and existing[0] != requestedTargetMoid:
            assignmentState = 'conflict'
            stateMessage = 'The Unified Edge profile is already assigned to a different entity.'
        elif existing:
            assignmentState = 'already'
            stateMessage = 'The Unified Edge profile is already assigned to the requested chassis.'
        else:
            assignmentState = 'assign'
            stateMessage = 'The Unified Edge profile is unassigned and ready for assignment.'
            patchBody = json.dumps({'AssignedEntity': {'ClassId': 'mo.MoRef', 'ObjectType': 'equipment.Chassis', 'Moid': requestedTargetMoid}, 'ChassisAssignmentMode': 'Static'}, separators=(',', ':'))
    else:
        raise ValueError('The single-target helper received an unsupported profile type.')
except Exception as exc:
    assignmentState = 'invalid'
    stateMessage = 'Assignment preflight validation failed: ' + str(exc)
stateResult = json.dumps({'profileType': profileType, 'profileMoid': profileMoid, 'targetMoid': requestedTargetMoid, 'state': assignmentState, 'message': stateMessage}, separators=(',', ':'))

