import sys
import json
profileType = sys.argv[1]
profileMoid = sys.argv[9]
expectedName = sys.argv[10]
targetMoid = sys.argv[7]
serverTargetObjectType = sys.argv[8]
verificationStatus = 'invalid'
verificationError = ''
try:
    response = json.loads(sys.argv[6])
    if str(response.get('Moid', '')).strip() != profileMoid:
        raise ValueError('The PATCH response Moid does not match the assigned profile.')
    if str(response.get('Name', '')).strip() != expectedName:
        raise ValueError('The PATCH response Name does not match the normalized requested profile name.')
    expectedProfileObjectTypes = {'Server': 'server.Profile', 'Chassis': 'chassis.Profile', 'Unified Edge': 'fabric.SwitchClusterProfile'}
    if str(response.get('ObjectType', '')).strip() != expectedProfileObjectTypes.get(profileType, ''):
        raise ValueError('The PATCH response ObjectType does not match the selected profile type.')
    if profileType == 'Server':
        field = 'AssignedServer'
        expectedType = serverTargetObjectType
        if str(response.get('ServerAssignmentMode', '')).strip() != 'Static':
            raise ValueError('The PATCH response does not confirm ServerAssignmentMode Static.')
    elif profileType == 'Chassis':
        field = 'AssignedChassis'
        expectedType = 'equipment.Chassis'
    elif profileType == 'Unified Edge':
        field = 'AssignedEntity'
        expectedType = 'equipment.Chassis'
    else:
        raise ValueError('Unsupported profile type for single-target verification.')
    if profileType in ('Chassis', 'Unified Edge') and response.get('ChassisAssignmentMode') != 'Static':
        raise ValueError('The PATCH response does not confirm ChassisAssignmentMode Static.')
    relation = response.get(field)
    if not isinstance(relation, dict):
        raise ValueError('The PATCH response does not contain ' + field + '.')
    if str(relation.get('Moid', '')).strip() != targetMoid:
        raise ValueError(field + ' does not reference the requested target Moid.')
    if str(relation.get('ObjectType', '')).strip() != expectedType:
        raise ValueError(field + ' does not contain the expected target ObjectType.')
    verificationStatus = 'valid'
except Exception as exc:
    verificationError = 'The accepted assignment response failed validation: ' + str(exc)

