import json
import sys
profileMoid = sys.argv[9]
requestedAMoid = sys.argv[7]
requestedBMoid = sys.argv[8]
assignmentState = 'invalid'
stateMessage = ''
stateResult = '{}'
childAMoid = ''
childBMoid = ''
assignFabricA = 'false'
assignFabricB = 'false'
fabricAPatchBody = ''
fabricBPatchBody = ''

def validate_target(raw, expectedMoid, side):
    item = json.loads(raw)
    if str(item.get('Moid', '')).strip() != expectedMoid:
        raise ValueError('Fabric ' + side + ' target response Moid does not match the requested Moid.')
    if str(item.get('ObjectType', '')).strip() != 'network.Element':
        raise ValueError('Fabric ' + side + ' target is not a network.Element.')
    if str(item.get('SwitchType', '')).strip() != 'FabricInterconnect':
        raise ValueError('Fabric ' + side + ' target is not a Fabric Interconnect.')
    if str(item.get('SwitchId', '')).strip() != side:
        raise ValueError('Fabric ' + side + ' target does not report SwitchId ' + side + '.')
    return item

def registered_device_moid(item, side):
    value = item.get('RegisteredDevice')
    if not isinstance(value, dict):
        raise ValueError('Fabric ' + side + ' target is missing its RegisteredDevice relationship.')
    moid = str(value.get('Moid', '')).strip()
    objectType = str(value.get('ObjectType', '')).strip()
    if not moid:
        raise ValueError('Fabric ' + side + ' target has an empty RegisteredDevice Moid.')
    if objectType != 'asset.DeviceRegistration':
        raise ValueError('Fabric ' + side + ' target has an unexpected RegisteredDevice ObjectType.')
    return moid

def relationships(child, expectedMoid, side):
    found = []
    for field in ('AssignedSwitch', 'AssociatedSwitch'):
        value = child.get(field)
        if value is None or value == {}:
            continue
        if not isinstance(value, dict):
            raise ValueError(field + ' on child ' + side + ' is not a relationship object.')
        moid = str(value.get('Moid', '')).strip()
        objectType = str(value.get('ObjectType', '')).strip()
        if not moid:
            raise ValueError(field + ' on child ' + side + ' is a non-empty relationship object without a usable Moid.')
        if objectType != 'network.Element':
            raise ValueError(field + ' on child ' + side + ' has an unexpected ObjectType.')
        found.append(moid)
    mode = child.get('SwitchAssignmentMode')
    if mode not in ('None', 'Static'):
        raise ValueError('SwitchAssignmentMode on child ' + side + ' is missing or unsupported.')
    if (mode == 'Static') != bool(found):
        raise ValueError('SwitchAssignmentMode on child ' + side + ' conflicts with assignment relationships.')
    if any((moid != expectedMoid for moid in found)):
        return 'conflict'
    return 'already' if found else 'assign'
try:
    targetA = validate_target(sys.argv[4], requestedAMoid, 'A')
    targetB = validate_target(sys.argv[5], requestedBMoid, 'B')
    if registered_device_moid(targetA, 'A') != registered_device_moid(targetB, 'B'):
        raise ValueError('Fabric A and Fabric B do not belong to the same registered domain.')
    if requestedAMoid == requestedBMoid:
        raise ValueError('Fabric A and Fabric B must be distinct.')
    envelope = json.loads(sys.argv[6])
    results = envelope.get('Results')
    if not isinstance(results, list):
        raise ValueError('The switch-profile response does not contain a Results array.')
    if len(results) != 2:
        raise ValueError('The domain profile must contain exactly two child switch profiles; received ' + str(len(results)) + '.')
    sides = {'A': [], 'B': []}
    for child in results:
        if not isinstance(child, dict):
            raise ValueError('A switch-profile result is not an object.')
        if str(child.get('ObjectType', '')).strip() != 'fabric.SwitchProfile':
            raise ValueError('A switch-profile result has an unexpected ObjectType.')
        side = str(child.get('SwitchId', '')).strip()
        if side not in sides:
            raise ValueError('Every child switch profile must have SwitchId A or B.')
        cluster = child.get('SwitchClusterProfile')
        if not isinstance(cluster, dict) or str(cluster.get('Moid', '')).strip() != profileMoid:
            raise ValueError('A child switch profile does not reference the selected cluster profile.')
        if str(cluster.get('ObjectType', '')).strip() != 'fabric.SwitchClusterProfile':
            raise ValueError('A child switch profile has an unexpected parent relationship ObjectType.')
        sides[side].append(child)
    if len(sides['A']) != 1 or len(sides['B']) != 1:
        raise ValueError('Exactly one SwitchId A child and one SwitchId B child are required.')
    childA = sides['A'][0]
    childB = sides['B'][0]
    childAMoid = str(childA.get('Moid', '')).strip()
    childBMoid = str(childB.get('Moid', '')).strip()
    if not childAMoid or not childBMoid or childAMoid == childBMoid:
        raise ValueError('Child switch profile Moids must be non-empty and distinct.')
    stateA = relationships(childA, requestedAMoid, 'A')
    stateB = relationships(childB, requestedBMoid, 'B')
    if 'conflict' in {stateA, stateB}:
        assignmentState = 'conflict'
        stateMessage = 'One or both child switch profiles are assigned or associated with a different Fabric Interconnect.'
    elif stateA == 'already' and stateB == 'already':
